-- QUALITY ASSESSMENT (§5.16 quality round, 2026-09-18). One nullable text
-- column: the reconciled quality assessment JSON (src/lib/work/quality.ts,
-- version-tagged) that the panel's new quality assessor/refuter pair
-- persists mid-run via setQualityAssessment (attempt-fenced, status
-- running). NULL forever on every pre-round row and whenever the assessor
-- call failed or WORK_QUALITY_ENABLED=0; every reader handles null, so
-- there is no backfill. Internal surfaces only (/admin/work and the
-- submitter's own /work/submit list); it never feeds card_json.
--
-- Generated by `drizzle-kit generate --name work_quality` against 0056's
-- snapshot (verified: 0057.prevId equals 0056.id); IF NOT EXISTS hand-added
-- per the 0044-onward convention, so a hand-applied catch-up on the VM can
-- run this file again without failing the deploy's db:migrate step.
ALTER TABLE "work_submissions" ADD COLUMN IF NOT EXISTS "quality_json" text;
